function M(){return HK.Moan;}
function P(){return HK.Pos;}
function rngOf(S){
var r=S&&S.rng?S.rng:S;
if(typeof r==='function')return r;
if(r&&r.int)return function(){return r.int(1000000)/1000000;};
return Math.random;
}
function pick(S,arr){
if(!arr|| !arr.length)return'';
var r=rngOf(S),base=function(l){return l[Math.floor(r()*l.length)];};
return E.fresh&&S?E.fresh(S,arr,base):base(arr);
}
function psOf(c){var p=c&&(HK.personaOf?HK.personaOf(c):c.persona);return PS9.indexOf(p)>=0?p:'gentle';}
function fill(s,r){return String(s).replace(/\{([a-z])\}/g,function(m,k){return r[k]&&r[k].name?r[k].name:m;});}
function unq(l){l=String(l||'');return l.charAt(0)==='「'&&l.charAt(l.length-1)==='」'?l.slice(1,-1):l;}
X.edgeKind=function(a,b){
var Q=P();
if(!Q|| !a|| !b)return'n';
if(HK.NoGen&&HK.NoGen.on&&HK.NoGen.on(a,b))return'n';
if(Q.hasM(a)&&(!Q.isF(a,b)||(Q.genSet&&Q.genSet(a)==='mf')))return'm';
if(Q.isF(a,b)&&Q.hasM(b)&& !Q.isF(b,a))return'fm';
if(Q.isF(a,b)&&Q.isF(b,a))return'ff';
return'n';
};
var edgeKind=X.edgeKind;
X.STRAP_P=0.25;
X.strapOk=function(a,b){var Q=P(),k=edgeKind(a,b);return(k==='fm'||k==='ff')&& !!Q&& !Q.hasM(a)&& !Q.noGen(a)&& !Q.noGen(b);};
function edgesOf(sp){
return({oneTwo:[[sp.t,sp.m],[sp.t,sp.u]],twoOne:[[sp.t,sp.u],[sp.m,sp.u]],sandwich:[[sp.t,sp.m],[sp.m,sp.u]],ring:[[sp.t,sp.m],[sp.m,sp.u],[sp.u,sp.t]],show:[[sp.t,sp.m]]})[sp.p]||[[sp.t,sp.u]];
}
