var hard=mode==='mf'&&T.hard(opt.rng,a,b),jl=hard&& !!opt.jealous,g=fmG(st),out=[];
var ET=HK.EroTop,eo=ET?{rel:opt.rel||ET.relOf(opt.ctx||opt.rng,a,b),kind:mode==='mf'?'m':mode,who:'{a}'}:null;
var tsay=function(stg){return ET?ET.say(opt.ctx||opt.rng,a,b,stg,eo):'';};
