var ffCand=ffList.filter(function(s){return riba|| !MUT|| !MUT.test(s);});
var ffBody=mode==='ff'?pick(ffCand.length?ffCand:ffList):'';
var body=mode==='ff'?ffBody:mode==='fm'?pick(T.FM_BODY[g]):pick(jl?T.JEALOUS_BODY:hard?T.ROUGH_BODY:T.BODY[st]||T.BODY.gentle);
