var mid0=(lt?MID_L:MID)[tp],mid= /正直|素直/.test(body)?mid0.filter(function(s){return!/正直|素直/.test(s);}):mid0;
out.push(pick(x,STRIP[k]));
say('b',PROTEST2[p]);
