var lv=tiesOf(x,T,B).filter(function(t){var D=HK.TIES[t.type];return D&&D.hate?t.b===T.i&&t.cold==='love':LOVE_T.test(t.type)&&(!dirTie(t)||t.a===T.i);});
var tw=one?(lv.length?lv.map(function(t){var D=HK.TIES[t.type];return D&&D.hate?'相手の気持ち：愛している':lab(t);}).join('・')+'。'+B.name+'を嫌っていない':B.name+'を嫌っていない'):T.name+'も'+B.name+'を嫌っている';
