if(HATE[id]&&(HATE[id]!=='dark'||dark)&&hostile.length)ev.push('敵対の組（'+hostile.map(function(t){return nm(t.a)+'×'+nm(t.b);}).slice(0,2).join('・')+'）');
var yan=OBS[id]?tiesOfType(B,/^yan$/).filter(function(t){return B.sexAny(t.a,t.b);}):[];
