var ab=force?tiesOfType(B,/^abuse$/).filter(function(t){return B.sexTB(t.a,t.b);}):[];
if(ab.length)ev.push('歪んだ関係の拒めない夜（'+ab.map(function(t){return nm(t.a)+'→'+nm(t.b);}).slice(0,2).join('・')+'）');
