if(nt==='sweet'||pb==='devoted'){we.again*=1.5;we.nagori*=1.4;}
if(!r18())we.hold*=1.3;
var oz=nt==='sadist'?0.45:nt==='mean'?0.4:(pt==='proud'||pt==='free')?0.1:0.05;
