if(k==='oazuke'){var a=(X0.OAZUKE_A||{})[p.pt]||(X0.OAZUKE_A||{}).gentle||[],b=(X0.OAZUKE_B||{})[p.pb]||(X0.OAZUKE_B||{}).gentle||[];return{every:function(f){return a.every(f)||b.every(f);},length:a.length&&b.length};}
